    if not lst[0] or all(c in ['(', ')'] for c in lst[0]):
        return 'Yes'

    # Check if the second string is empty or contains only open parentheses
    if not lst[1] or all(c in [')', '('] for c in lst[1]):
        return 'No'

    # Concatenate the two strings and check if it's balanced
    combined = lst[0] + lst[1]
