def do_algebra(operator, operand):
    # Check if the lengths are correct
    if len(operator) != len(operand) - 1:
        return None

    result = operand[0]
    for i in range(len(operator)):
        op = operator[i]
        num2 = operand[i + 1]

        if op == '+':
            result += num2
        elif op == '-':
            result -= num2
        elif op == '*':
            result *= num2
        elif op == '//':
            result //= num2
        elif op == '**':
            result **= num2

    return result
```

