def solve(s):
    # Check if the string contains any letters
    has_letters = False
    for char in s:
        if char.isalpha():
            has_letters = True
            break

    # If no letters are found, reverse the entire string
    if not has_letters:
        return s[::-1]

    # Otherwise, process each character based on its case
    result = []
    for i, char in enumerate(s):
        if char.isalpha():
            # Reverse the case of the letter
            reversed_case = char.swapcase()
            result.append(reversed_case)
        else:
            # Keep non-letter characters as they are
            result.append(char)

    return ''.join(result)
